/** Entrada del paso: W77-FUNCION y W77-SISTEMA. */
public record ControlEstatusRequest(
        int funcion,          // 9(02): 2 = inicio de jornada, 3 = fin de jornada, otro = solo consulta
        int sistema) {        // 9(03): se amplía a 9(04) al pasar a las librerías
    public boolean escribeEstatus() { return funcion == 2 || funcion == 3; }
}

/** Salida: los cinco parámetros que P655 rellena por referencia para el WFL. */
public record ControlEstatusResult(
        String nomPacMov,     // X(17) pack de movimientos
        String nomPacDes,     // X(17) pack de descuentos
        String nomPacErr,     // X(17) pack de errores
        String nomPacSal,     // X(17) pack de saldos
        String nomBdSal,      // X(17) base de saldos del ciclo
        EstadoActualizacion estatus) {}

public enum EstadoActualizacion { NO_APLICA, ACTUALIZADO, FALLO_CONSULTA, FALLO_ACTUALIZACION }

/** Dataset DMSII S151B04SISTEM migrado; llave sistema + producto + instrumento. */
@Entity
@Table(name = "s151_sistema")
public class SistemaS151 {

    @EmbeddedId
    private SistemaId id;                  // WKS-B04-SISTEMA 9(04), PRODUCTO 9(04), INSTRUM 9(04)

    @Column(name = "nom_corto", length = 20) private String nomCorto;   // WKS-B04-NOMCOR X(20)
    @Column(name = "nom_largo", length = 40) private String nomLargo;   // WKS-B04-NOMLAR X(40)

    @Column(name = "estatus", nullable = false)
    private int estatus;                   // WKS-B04-ESTATUS 9(02): 2 inicio, 3 fin de jornada

    @Version
    private long version;                  // sustituye la consulta previa obligatoria (función 1)
}

@Embeddable
public record SistemaId(int sistema, int producto, int instrumento) implements Serializable {}

public interface SistemaS151Repository extends JpaRepository<SistemaS151, SistemaId> {
    /** P655 solo conoce el sistema; producto e instrumento no se envían. */
    List<SistemaS151> findByIdSistema(int sistema);
}

@Component
@StepScope
@RequiredArgsConstructor
public class ControlEstatusSistemaTasklet implements Tasklet {   // PROGRAM-ID CALLLIBCTL

    private final ControlS151Service control;   // reemplaza las entradas de LIBCTL
    @Value("#{jobParameters['funcion']}") private Integer funcion;
    @Value("#{jobParameters['sistema']}") private Integer sistema;

    @Override
    public RepeatStatus execute(StepContribution contribution, ChunkContext ctx) {
        var req = new ControlEstatusRequest(funcion, sistema);
        var dia = control.datosDia(req.sistema());          // 000310-CONSULTA-B01
        var mes = control.datosMes(req.sistema());          // 000320-CONSULTA-B03
        var estado = EstadoActualizacion.NO_APLICA;
        if (req.escribeEstatus()) {                          // IF W77-FUNCION = 2 OR 3
            estado = control.cambiaEstatus(req.sistema(), req.funcion());  // CONSULTA-B04 + CAMBIA-B04
        }
        var res = new ControlEstatusResult(dia.nomPacMov(), dia.nomPacDes(), dia.nomPacErr(),
                dia.nomPacSal(), mes.nomBdSal(), estado);
        ctx.getStepContext().getStepExecution().getJobExecution()
           .getExecutionContext().put("p655", res);

        if (estado == EstadoActualizacion.FALLO_ACTUALIZACION) {
            contribution.setExitStatus(new ExitStatus("ESTATUS_NO_ACTUALIZADO"));   // el WFL lo decide
        }
        return RepeatStatus.FINISHED;
    }
}

# application.yml
s151:
  libctl:
    lib-id: S151L001CTL
    respaldo: "(S151)S151/OBJECT/L001/CONTROL ON CMEMP"   # solo documental en el destino
  datasource:
    control:
      url: jdbc:postgresql://s151-control/s151        # lo que antes resolvía CTLVER

// ---------------------------------------------------------------------------
@Configuration
public class ControlS151Config {

    /**
     * 000200-LIBRERIAS: CTLVER entrega el título vigente de LIBCTL y, si falla,
     * se usa uno fijo. En el destino la versión la fija el despliegue y la
     * conexión se valida al arrancar: no hay respaldo silencioso a otra versión.
     */
    @Bean
    @ConfigurationProperties("s151.datasource.control")
    DataSource controlDataSource() {
        return DataSourceBuilder.create().build();
    }

    @Bean
    HealthIndicator controlS151Health(DataSource controlDataSource) {
        return new DataSourceHealthIndicator(controlDataSource, "select 1");
    }
}

@Service
@RequiredArgsConstructor
public class ControlS151Service {

    private final SistemaDiaRepository b01;    // S151B01SISDIA (entrada CONSISDIA)
    private final SistemaMesRepository b03;    // S151B03SISMEN (entrada CONSISMEN)
    private final SistemaS151Repository b04;

    /** 000310-CONSULTA-B01. Sin registro: se informa vacío, no el valor anterior. */
    public DatosDia datosDia(int sistema) {
        return b01.findBySistema(sistema)
                .map(d -> new DatosDia(d.nomPacMov(), d.nomPacDes(), d.nomPacErr(), d.nomPacSal()))
                .orElseGet(() -> {
                    log.warn("CONSISDIA sin datos para sistema {}", sistema);
                    return DatosDia.VACIO;
                });
    }

    /** 000320-CONSULTA-B03. */
    public DatosMes datosMes(int sistema) {
        return b03.findBySistema(sistema)
                .map(m -> new DatosMes(m.nomBdSal()))
                .orElseGet(() -> {
                    log.warn("CONSISMEN sin datos para sistema {}", sistema);
                    return DatosMes.VACIO;
                });
    }
}

/** 000320-CONSULTA-B04 + 000320-CAMBIA-B04: el estatus nuevo es el código de función. */
@Transactional
public EstadoActualizacion cambiaEstatus(int sistema, int funcion) {
    List<SistemaS151> regs = b04.findByIdSistema(sistema);       // función 1
    if (regs.isEmpty()) {
        log.error("ERROR AL CONSULTAR B04 sistema={}", sistema);
        return EstadoActualizacion.FALLO_CONSULTA;               // el original seguía y escribía
    }
    if (regs.size() > 1) {
        throw new IllegalStateException(
            "B04 tiene " + regs.size() + " registros para el sistema " + sistema
            + "; P655 no envía producto ni instrumento");
    }
    try {
        regs.get(0).setEstatus(funcion);                         // MOVE W77-FUNCION TO WKS-B04-ESTATUS
        b04.flush();                                             // función 37 (MANTB04SISTEM)
        return EstadoActualizacion.ACTUALIZADO;
    } catch (OptimisticLockingFailureException e) {
        log.error("ERROR AL ACTUALIZAR B04 sistema={}", sistema, e);
        return EstadoActualizacion.FALLO_ACTUALIZACION;
    }
}
